4	namespace WPMedia\BackWPup\Admin\Notices;
5	
6	use WPMedia\BackWPup\EventManagement\SubscriberInterface;
7	use WPMedia\BackWPup\Admin\Notices\Notices\AbstractNotice;
8	
9	/**
10	 * Subscriber class responsible for rendering admin notices.
11	 */
12	class Subscriber implements SubscriberInterface {
13		/**
14		 * Array of notice instances to be rendered.
15		 *
16		 * @var AbstractNotice[]
17		 */
18		private array $notices;
19	
20		/**
21		 * Notices instance.
22		 *
23		 * @var Notices
24		 */
25		private Notices $admin_notices;
26	
27		/**
28		 * Constructor.
29		 *
30		 * @param Notices          $admin_notices The Notices instance.
31		 * @param AbstractNotice[] $notices Array of notice instances.
32		 */
33		public function __construct( Notices $admin_notices, $notices ) {
34			$this->notices       = $notices;
35			$this->admin_notices = $admin_notices;
36		}
37	
38		/**
39		 * Returns the events this subscriber wants to listen to.
40		 *
41		 * @return array
42		 */
43		public static function get_subscribed_events() {
44			return [
45				'all_admin_notices'                  => [
46					[ 'render_all_notices' ],
47					[ 'display_update_notice' ],
48					[ 'display_license_notice' ],
49				],
50				'wp_ajax_backwpup_dismiss_notice'    => 'backwpup_dismiss_notices',
51				'admin_post_backwpup_dismiss_notice' => 'backwpup_dismiss_notices',
52			];
53		}
54	
55		/**
56		 * Renders all registered notices on the admin_notices hook.
57		 *
58		 * @return void
59		 */
60		public function render_all_notices() {
61			foreach ( $this->notices as $notice ) {
62				$notice->maybe_render();
63			}
64		}
65	
66		/**
67		 * Display updates notices.
68		 *
69		 * @return void
70		 */
71		public function display_update_notice(): void {
72			$this->admin_notices->display_update_notices();
73		}
74	
75		/**
76		 * Display license notice.
77		 *
78		 * @return void
79		 */
80		public function display_license_notice(): void {
81			$this->admin_notices->display_license_notice();
82		}
83	
84		/**
85		 * Dismiss notice update.
86		 *
87		 * @return void
88		 */
89		public function backwpup_dismiss_notices(): void {
90			$this->admin_notices->backwpup_dismiss_notices();
91		}
92	}
