@use "sass:color";
@use "../settings/colors";

//
// Notice
//
$color-brand-darker: color.adjust(colors.$color-brand, $lightness: -5%);
.notice-inpsyde{
  &.notice-success {
    border-left-color: colors.$color-brand;
  }
}

.notice-inpsyde{
  &.notice-info {
    border-right-color: rgb(204 204 204 / var(--tw-border-opacity, 1));
    border-bottom-color: rgb(204 204 204 / var(--tw-border-opacity, 1));
    border-top-color: rgb(204 204 204 / var(--tw-border-opacity, 1));
    border-style: solid;
    border-right-width: 1px;
    border-top-width: 1px;
    border-bottom-width: 1px;
  }
}

.notice-inpsyde {
  position: relative;
  margin-left: 2px;

  a.bwu-onboarding-optin, a.bwu-onboarding-optin:hover {
	color: #0073aa;
	font-weight: normal;
  }

  a.bwu-onboarding-optin:hover {
	text-decoration: underline;
  }

  a {
    font-weight: bold;
    color: inherit;
    text-decoration: none;
  }

  &.notice-backwpup_rate {

    padding: 20px;

    .font-title {
      font-size: 26px;
      font-weight: 400;

      span {
        font-weight: 700;
      }
    }

    a {
      font-weight: normal;
    }

    .notice-message {
      p {
        font-size: 1.125rem;
        line-height: 1.125rem;
      }
      margin-bottom: 20px;
    }

    .button {
      font-size: 1rem;
      line-height: 1.5rem;
      padding: 12px 1.5rem;
      letter-spacing: inherit;

      &.button-secondary {
        background-color: transparent;
        border: none;
      }
    }
  }

  // Button
  .button--inpsyde {
    background-color: colors.$color-brand;
    color:            colors.$color-white;
    border-color:     $color-brand-darker;
    box-shadow:       0 1px 0 $color-brand-darker;

    &:hover,
    &:focus {
      background-color: $color-brand-darker;
      border-color:     color.adjust($color-brand-darker, $lightness: -5%);
      box-shadow:       0 1px 0 $color-brand-darker, 0 0 3px colors.$color-brand;
      color:            colors.$color-white;
    }
  }

  .notice-titre {
    font-size: 21px;
    margin: .5em 0;
    padding: 2px;
    font-weight: bold;
  }

  .notice-content {
    margin-bottom: 1em;
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    font-size: 18px;
  }

  .notice-actions a{
    line-height: 1.7;
  }


  .closeIt {
    position: absolute;
    top: 0;
    right: 0;
    cursor: pointer;
    padding: 10px 15px 10px 24px;
    text-decoration: none;
  }

  .closeIt:focus {
    box-shadow: none;
  }

  .closeIt:before {
    position: absolute;
    top: 9px;
    left: 0;
    transition: all .1s ease-in-out;
    content: '\f335';
    font: normal 16px/20px dashicons;
    font-size: 24px;
    height: 20px;
    text-align: center;
    width: 20px;
  }

  #backwpup_notice_evaluate_step_review, #backwpup_notice_evaluate_step_issue, #backwpup_notice_evaluate_step_thanks {
    display: none;
  }
}

